def default_latex_symbol(name: str) -> str:
    """Return safe default LaTeX for a variable name (uses hyphens to avoid KaTeX subscript issues)."""
    return r'\mathrm{' + name.replace('_', '-') + r'}'


SPECIAL_LATEX_SYMBOL_OVERRIDES = {
    # Keep helper constants readable in equations without underscore subscript parsing.
    'DATA_FORMAT_TO_BYTES': r'\mathrm{DataFormatToBytes}',
}


def latex_symbol_for(name: str) -> str:
    """Return custom LaTeX symbol if provided, else safe default."""
    special = SPECIAL_LATEX_SYMBOL_OVERRIDES.get(name, '')
    if special:
        return special
    custom = LATEX_SYMBOL_OVERRIDES.get(name, '')
    return custom if custom else default_latex_symbol(name)


def _formula_to_latex_expr(expr: str) -> str:
    """Convert a Python-style formula string into a LaTeX expression with vertical fractions."""

    cmp_ops = {
        ast.Lt: '<',
        ast.LtE: r'\le',
        ast.Gt: '>',
        ast.GtE: r'\ge',
        ast.Eq: '=',
        ast.NotEq: r'\ne',
    }

    bool_ops = {
        ast.And: r'\land',
        ast.Or: r'\lor',
    }

    func_names = {
        'MIN': r'\min',
        'MAX': r'\max',
        'CEILING': r'\mathrm{CEILING}',
        'FLOOR': r'\mathrm{FLOOR}',
        'IF': r'\mathrm{IF}',
    }

    def _wrap(text: str) -> str:
        return r'\left(' + text + r'\right)'

    def _render(node: ast.AST, parent_prec: int = 0) -> str:
        # Precedence: compare/bool=1, add/sub=2, mul/div=3, pow=4, atom/call=5
        if isinstance(node, ast.Name):
            return latex_symbol_for(node.id)

        if isinstance(node, ast.Constant):
            return str(node.value)

        if isinstance(node, ast.Subscript):
            base = _render(node.value, 5)
            index = _render(node.slice, 0)
            return f'{base}[{index}]'

        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            fn = func_names.get(node.func.id, node.func.id)
            args = ', '.join(_render(a, 0) for a in node.args)
            return f'{fn}({args})'

        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.USub):
                return '-' + _render(node.operand, 5)
            if isinstance(node.op, ast.UAdd):
                return _render(node.operand, 5)

        if isinstance(node, ast.BinOp):
            if isinstance(node.op, ast.Add):
                prec = 2
                left = _render(node.left, prec)
                right = _render(node.right, prec)
                out = f'{left} + {right}'
                return _wrap(out) if prec < parent_prec else out

            if isinstance(node.op, ast.Sub):
                prec = 2
                left = _render(node.left, prec)
                right = _render(node.right, prec + 1)
                out = f'{left} - {right}'
                return _wrap(out) if prec < parent_prec else out

            if isinstance(node.op, ast.Mult):
                prec = 3
                left = _render(node.left, prec)
                right = _render(node.right, prec)
                out = f'{left} \\times {right}'
                return _wrap(out) if prec < parent_prec else out

            if isinstance(node.op, ast.Div):
                prec = 3
                num = _render(node.left, 0)
                den = _render(node.right, 0)
                out = rf'\frac{{{num}}}{{{den}}}'
                return _wrap(out) if prec < parent_prec else out

            if isinstance(node.op, ast.Pow):
                prec = 4
                base = _render(node.left, prec)
                exp = _render(node.right, 0)
                out = rf'{base}^{{{exp}}}'
                return _wrap(out) if prec < parent_prec else out

        if isinstance(node, ast.Compare) and len(node.ops) == 1 and len(node.comparators) == 1:
            op = cmp_ops.get(type(node.ops[0]), '?')
            left = _render(node.left, 1)
            right = _render(node.comparators[0], 1)
            return f'{left} {op} {right}'

        if isinstance(node, ast.BoolOp):
            op = bool_ops.get(type(node.op), '?')
            return f' {op} '.join(_render(v, 1) for v in node.values)

        return _wrap(ast.unparse(node))

    tree = ast.parse(expr, mode='eval')
    return _render(tree.body, 0)


def _split_top_level_additive(expr: str) -> list[str]:
    """Split a LaTeX expression at top-level + and - operators (brace/paren-depth-aware)."""
    parts: list[str] = []
    depth = 0        # { } depth
    pdepth = 0       # \left( ... \right) depth
    i = 0
    start = 0
    while i < len(expr):
        if expr[i] == '{':
            depth += 1
        elif expr[i] == '}':
            depth -= 1
        elif expr[i:i+6] == r'\left(':
            pdepth += 1
            i += 5
        elif expr[i:i+7] == r'\right)':
            pdepth -= 1
            i += 6
        elif expr[i] in '+-' and depth == 0 and pdepth == 0:
            # binary operator: surrounded by spaces
            if i > 0 and expr[i - 1] == ' ' and i + 1 < len(expr) and expr[i + 1] == ' ':
                parts.append(expr[start:i].strip())
                start = i  # keep operator with following term
        i += 1
    tail = expr[start:].strip()
    if tail:
        parts.append(tail)
    return parts


def _brace_extract(s: str, start: int) -> tuple[str, int]:
    """Extract the content of balanced braces starting at index 'start' (must be '{').
    Returns (content, index_after_closing_brace)."""
    assert s[start] == '{'
    depth = 0
    i = start
    while i < len(s):
        if s[i] == '{':
            depth += 1
        elif s[i] == '}':
            depth -= 1
            if depth == 0:
                return s[start + 1:i], i + 1
        i += 1
    raise ValueError('Unmatched brace in LaTeX expression')


def _extract_top_frac(s: str) -> tuple[str, str] | None:
    """If s is exactly \\frac{num}{den} with nothing trailing, return (num, den), else None."""
    prefix = r'\frac{'
    if not s.startswith(prefix):
        return None
    try:
        num, after_num = _brace_extract(s, len(prefix) - 1)
        if after_num >= len(s) or s[after_num] != '{':
            return None
        den, after_den = _brace_extract(s, after_num)
        if after_den != len(s):
            return None
        return num, den
    except (ValueError, AssertionError):
        return None


def _make_aux_symbol(lhs: str, suffix: str) -> str:
    """Return a parenthesized symbol with subscript for recursive decomposition."""
    return f'\\left({lhs}\\right)_{{{suffix}}}'


def _extract_leading_left_right_group(s: str) -> tuple[str, str] | None:
    r"""If s starts with \left( ... \right), return (inside, trailing_suffix)."""
    if not s.startswith(r'\left('):
        return None
    depth = 0
    i = 0
    while i < len(s):
        if s[i:i + 6] == r'\left(':
            depth += 1
            i += 6
            continue
        if s[i:i + 7] == r'\right)':
            depth -= 1
            i += 7
            if depth == 0:
                inner = s[6:i - 7]
                suffix = s[i:]
                return inner, suffix
            continue
        i += 1
    return None


def _equation_block(lhs: str, rhs: str, threshold: int = 100) -> str:
    """Return one or more markdown display-math blocks.

    Short equations:  single $$ ... $$ line.
    Long additive RHS: one aligned block split at top-level +/-.
    Long fraction RHS: three equations —
        (1) lhs = lhs_{num} / lhs_{den}  (or  lhs = lhs_{num} / simple_den)
        (2) lhs_{num} = <numerator>       (recursively wrapped if still long)
        (3) lhs_{den} = <denominator>     (only when denominator is complex)
    """
    if len(lhs) + len(rhs) + 5 <= threshold:
        return f'$$ {lhs} = {rhs} $$'

    # Case 1: top-level additive — split on + / -
    parts = _split_top_level_additive(rhs)
    if len(parts) > 1:
        extra_blocks: list[str] = []
        display_parts: list[str] = [parts[0]]

        for i, p in enumerate(parts[1:], start=1):
            sign = ''
            body = p
            if p.startswith('+ ') or p.startswith('- '):
                sign = p[:2]
                body = p[2:]

            # If a single additive term is still very long, extract a leading
            # parenthesized chunk into an auxiliary symbol and render it below.
            # This avoids overly wide lines like: +(A - (B + C + ...)) * R.
            group = _extract_leading_left_right_group(body) if len(p) > threshold else None
            if group:
                group_inner, group_suffix = group
                group_parts = _split_top_level_additive(group_inner)
                if len(group_parts) > 1:
                    aux = _make_aux_symbol(lhs, rf'\mathrm{{aux{i}}}')
                    display_parts.append(f'{sign}{aux}{group_suffix}')
                    extra_blocks.append(_equation_block(aux, group_inner, threshold))
                    continue

            display_parts.append(p)

        inner = f'{lhs} &= {display_parts[0]}'
        for p in display_parts[1:]:
            inner += f' \\\\\n&\\quad {p}'

        main_block = f'$$\n\\begin{{aligned}}\n{inner}\n\\end{{aligned}}\n$$'
        if not extra_blocks:
            return main_block
        return main_block + '\n\n' + '\n\n'.join(extra_blocks)

    # Case 2: single top-level \frac — decompose into 2 or 3 sub-equations
    frac = _extract_top_frac(rhs)
    if frac:
        num, den = frac
        component_long_threshold = max(120, threshold)
        num_is_very_long = len(num) > component_long_threshold
        den_is_very_long = len(den) > component_long_threshold

        # Keep compact fractions as a single equation even when lhs is long.
        if not num_is_very_long and not den_is_very_long:
            return f'$$ {lhs} = {rhs} $$'

        lhs_num = _make_aux_symbol(lhs, r'\mathrm{num}')
        den_is_simple = len(den) < 50 and r'\frac' not in den
        if den_is_simple:
            summary = f'$$ {lhs} = \\frac{{{lhs_num}}}{{{den}}} $$'
            num_block = _equation_block(lhs_num, num, threshold)
            return summary + '\n\n' + num_block
        else:
            lhs_den = _make_aux_symbol(lhs, r'\mathrm{den}')
            summary = f'$$ {lhs} = \\frac{{{lhs_num}}}{{{lhs_den}}} $$'
            num_block = _equation_block(lhs_num, num, threshold)
            den_block = _equation_block(lhs_den, den, threshold)
            return summary + '\n\n' + num_block + '\n\n' + den_block

    return f'$$ {lhs} = {rhs} $$'


def _format_equation_header(row: int | str, name: str, max_chars: int = 56) -> list[str]:
    """Format equation section headers and wrap long names at underscore boundaries."""
    words = name.split('_')
    wrapped: list[str] = []
    current: list[str] = []
    current_len = 0

    for w in words:
        add_len = len(w) + (1 if current else 0)
        if current and current_len + add_len > max_chars:
            wrapped.append(' '.join(current))
            current = [w]
            current_len = len(w)
        else:
            current.append(w)
            current_len += add_len

    if current:
        wrapped.append(' '.join(current))

    if not wrapped:
        return [f'### row {row}']

    lines = [f'### row {row} - {wrapped[0]}']
    for tail in wrapped[1:]:
        lines.append(f'### {tail}')
    return lines


def build_equations_markdown(output_order: str = 'execution') -> str:
    """Build equations markdown using LATEX_SYMBOL_OVERRIDES + PYTHON_FORMULAS."""
    internal_order = _resolve_output_order(output_order)
    item_order = COMPUTE_ORDER if internal_order == 'compute' else ROW_ORDER

    lines: list[str] = []
    lines.append('# GEMM Analytical Model - Equations')
    lines.append('')
    lines.append('Auto-generated from PYTHON_FORMULAS and LATEX_SYMBOL_OVERRIDES in gemmanalytics.py.')
    lines.append('')
    lines.append(f'Output order: {output_order}')
    lines.append('')

    for name in item_order:
        formula = PYTHON_FORMULAS.get(name, '')
        if not formula:
            continue
        row = ROW_INDEX.get(name, '?')
        lines.extend(_format_equation_header(row, name))
        lines.append('')
        lhs = latex_symbol_for(name)
        rhs = _formula_to_latex_expr(formula)
        lines.append(_equation_block(lhs, rhs))
        lines.append('')

    return '\n'.join(lines).rstrip() + '\n'


def export_equations_markdown(md_path: str, output_order: str = 'execution') -> None:
    """Write generated equation markdown file."""
    content = build_equations_markdown(output_order=output_order)
    with open(md_path, 'w', encoding='utf-8') as f:
        f.write(content)
