def format_value_for_report(name: str, value):
    if name in PERCENT_NAMES and isinstance(value, (int, float)):
        return format(value, '.2%')
    return value

def _resolve_output_order(output_order: str) -> str:
    """Normalize output-order values to internal order keys.

    Returns:
        'compute' for execution order or 'xlsx' for row-tracking order.
    """
    if output_order == 'execution':
        return 'compute'
    if output_order == 'row_tracking':
        return 'xlsx'
    raise ValueError(f'Unsupported output order: {output_order}')


def build_normal_report(values: dict, output_order: str = 'execution') -> str:
    """Build normal report with structure matching output_order.
    
    Args:
        values: dict of computed values
        output_order: 'execution' for 4-section compute flow, 'row_tracking' for 5-section domain structure
    """
    internal_order = _resolve_output_order(output_order)
    item_order = COMPUTE_ORDER if internal_order == 'compute' else ROW_ORDER
    out: list[str] = []
    out.append(f'Source: {SOURCE_XLSX}  Sheet: {SOURCE_SHEET}')
    out.append('')
    out.append('--- NORMAL MODE ---')
    out.append('')
    
    if internal_order == 'compute':
        # 4-section structure following compute execution order
        out.append('[1] MACHINE PARAMETERS (PRE-DEFINED)')
        for name in item_order:
            if name in MACHINE_PRE_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
        out.append('')
        
        out.append('[2] WORKLOAD PARAMETERS (PRE-DEFINED)')
        for name in item_order:
            if name in FORMAT_KEY_NAMES or name in WORKLOAD_PRE_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
        out.append('')
        
        out.append('[3] DERIVED PARAMETERS')
        for name in item_order:
            if name in (WORKLOAD_FMT_VAL_NAMES + MACHINE_DERIVED_NAMES + MACHINE_WL_DERIVED_NAMES + WORKLOAD_DERIVED_NAMES):
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
        out.append('')
        
        out.append('[4] MACHINE STATS')
        for name in item_order:
            if name in MACHINE_STATS_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
    else:
        # 5-section structure organized by domain and type (row_tracking)
        out.append('[1] WORKLOAD PARAMETERS (PRE-DEFINED)')
        for name in item_order:
            if name in FORMAT_KEY_NAMES or name in WORKLOAD_PRE_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
        out.append('')
        out.append('[2] WORKLOAD PARAMETERS (DERIVED)')
        for name in item_order:
            if name in WORKLOAD_FMT_VAL_NAMES or name in WORKLOAD_DERIVED_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
        out.append('')
        out.append('[3] MACHINE PARAMETERS (PRE-DEFINED)')
        for name in item_order:
            if name in MACHINE_PRE_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
        out.append('')
        out.append('[4] MACHINE PARAMETERS (DERIVED)')
        for name in item_order:
            if name in MACHINE_DERIVED_NAMES or name in MACHINE_WL_DERIVED_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
        out.append('')
        out.append('[5] MACHINE STATS')
        for name in item_order:
            if name in MACHINE_STATS_NAMES:
                if name in values:
                    val = format_value_for_report(name, values[name])
                    out.append(f'  {name} = {val}')
    out.append('')
    return '\n'.join(out)

def build_debug_report(values: dict) -> str:
    out: list[str] = []
    out.append(f'Source: {SOURCE_XLSX}  Sheet: {SOURCE_SHEET}')
    out.append('')
    out.append('--- DEBUG MODE (ORIGINAL XLSX ROW ORDER) ---')
    for name in ROW_ORDER:
        if name not in values:
            continue
        row = ROW_INDEX.get(name, '?')
        cat = CATEGORY_MAP.get(name, '')
        display_name = f'{name}_C{row}'
        val = format_value_for_report(name, values[name])
        if name in FORMAT_KEY_NAMES or name in WORKLOAD_PRE_NAMES or name in MACHINE_PRE_NAMES:
            out.append(f'  row {row} [{cat}]: {display_name} = {val}')
        else:
            formula = PYTHON_FORMULAS.get(name, '')
            out.append(f'  row {row} [{cat}]: {display_name}')
            out.append(f'    formula : {formula}')
            out.append(f'    result  : {val}')
    out.append('')
    return '\n'.join(out)

def export_to_csv(values: dict, csv_path: str, output_order: str = 'execution') -> None:
    """Export model values to CSV with metadata (Name, Value, Category, Row, Label).
    
    Args:
        values: dict of computed values
        csv_path: output CSV file path
        output_order: 'execution' for compute order (default), 'row_tracking' for xlsx row order
    """
    internal_order = _resolve_output_order(output_order)
    item_order = COMPUTE_ORDER if internal_order == 'compute' else ROW_ORDER
    with open(csv_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['Name', 'Value', 'Category', 'Row', 'Label'])
        for name in item_order:
            if name not in values:
                continue
            writer.writerow([name, values[name], CATEGORY_MAP.get(name, ''), ROW_INDEX.get(name, ''), ''])

def parse_cli_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description='Run GEMM model with workload and machine parameters.')
    parser.add_argument('--workload-params', required=True, metavar='CSV', help='Workload parameters CSV (Name,Value[,Label])')
    parser.add_argument('--machine-params', required=True, metavar='CSV', help='Machine parameters CSV (Name,Value[,Label])')
    parser.add_argument('--mode', choices=['normal', 'debug'], default='normal', help='normal: 5-section summary; debug: row-order detail with formulas')
    parser.add_argument('--output-order', choices=['execution', 'row_tracking'], default='execution', help="output order: 'execution' for 4-section compute order (default), 'row_tracking' for original xlsx row order")
    parser.add_argument('--output-txt', default=None, help='(Optional) also write text report to file')
    parser.add_argument('--output-csv', default=None, help='(Optional) also export model values to CSV')
    parser.add_argument('--output-equations-md', default=None, metavar='MD', help='(Optional) export equations markdown using LaTeX symbol mapping')
    parser.add_argument('--no-stdout', action='store_true', help='Suppress stdout output')
    return parser.parse_args()

def main() -> None:
    args = parse_cli_args()
    workload_params = _load_params_csv(args.workload_params, ALL_WORKLOAD_PRE_NAMES, 'workload', ALL_PRE_NAMES_SET)
    machine_params  = _load_params_csv(args.machine_params,  MACHINE_PRE_NAMES,       'machine',  ALL_PRE_NAMES_SET)
    values = compute_core_values(workload_params, machine_params)
    report = build_debug_report(values) if args.mode == 'debug' else build_normal_report(values, output_order=args.output_order)
    if not args.no_stdout:
        print(report)
    if args.output_txt:
        with open(args.output_txt, 'w', encoding='utf-8') as f:
            f.write(report)
    if args.output_csv:
        export_to_csv(values, args.output_csv, output_order=args.output_order)
    if args.output_equations_md:
        export_equations_markdown(args.output_equations_md, output_order=args.output_order)

if __name__ == '__main__':
    main()
